// HTML escaping for server-rendered dashboard fragments.

const ENTITIES: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

// Safe for element content and for quoted attribute values.
export function escapeHtml(text: string): string {
  return String(text).replace(/[&<>"']/g, (ch) => ENTITIES[ch]);
}

// The jobs table on the dashboard: JobDto[] in, an HTML fragment out. Pure functions only.
import type { JobDto } from "../../api/src/serialize.ts";
import { formatDuration } from "../../core/src/duration.ts";
import { pluralize, truncate } from "../../core/src/strings.ts";
import { escapeHtml } from "./html.ts";

export type SortKey = "name" | "status" | "nextRunAt";

export interface SortSpec {
  key: SortKey;
  dir: "asc" | "desc";
}

export interface TableOptions {
  now: Date;
  sort?: SortSpec;
  selectedId?: string;
  // Visible characters of the command before it is cut with an ellipsis; the full
  // command is always available in the cell's tooltip.
  commandWidth?: number;
}

const STATUS_CLASS: Record<string, string> = {
  queued: "badge badge-info",
  running: "badge badge-active",
  succeeded: "badge badge-ok",
  failed: "badge badge-error",
  cancelled: "badge badge-muted",
};

const COLUMNS: Array<{ key: SortKey | null; label: string }> = [
  { key: "name", label: "Name" },
  { key: null, label: "Command" },
  { key: "status", label: "Status" },
  { key: "nextRunAt", label: "Next run" },
];

// "in 5m", "2h ago", "now", or an em dash when there is no upcoming run.
export function relativeLabel(iso: string | null, now: Date): string {
  if (!iso) return "\u2014";
  const diff = Date.parse(iso) - now.getTime();
  if (Math.abs(diff) < 1_000) return "now";
  const text = formatDuration(Math.abs(diff)).split(" ")[0];
  return diff > 0 ? `in ${text}` : `${text} ago`;
}

// A sorted copy of `jobs`. Ties are broken by id so the order is stable. Jobs without
// a next run always go last when sorting by next run, whatever the direction.
export function sortJobs(jobs: readonly JobDto[], sort?: SortSpec): JobDto[] {
  const copy = [...jobs];
  if (!sort) return copy;
  const factor = sort.dir === "desc" ? -1 : 1;
  return copy.sort((a, b) => {
    const av = a[sort.key] ?? "";
    const bv = b[sort.key] ?? "";
    if (av !== bv) return av < bv ? -factor : factor;
    return a.id.localeCompare(b.id);
  });
}

export function renderJobRow(job: JobDto, options: TableOptions): string {
  const width = options.commandWidth ?? 32;
  const selected = job.id === options.selectedId ? ' class="selected" aria-selected="true"' : "";
  return [
    `<tr data-id="${escapeHtml(job.id)}"${selected}>`,
    `<td class="name">${escapeHtml(job.name)}</td>`,
    `<td class="command" title="${escapeHtml(job.command)}">${truncate(escapeHtml(job.command), width)}</td>`,
    `<td class="status"><span class="${STATUS_CLASS[job.status] ?? "badge"}">${escapeHtml(job.status)}</span></td>`,
    `<td class="next">${escapeHtml(relativeLabel(job.nextRunAt, options.now))}</td>`,
    "</tr>",
  ].join("");
}

export function renderJobsTable(jobs: readonly JobDto[], options: TableOptions): string {
  if (jobs.length === 0) return '<p class="empty">No jobs match these filters.</p>';
  const head = COLUMNS.map((col) => {
    const sorted = options.sort !== undefined && col.key === options.sort.key;
    const aria = sorted ? ` aria-sort="${options.sort?.dir === "desc" ? "descending" : "ascending"}"` : "";
    return `<th scope="col"${aria}>${col.label}</th>`;
  }).join("");
  const rows = sortJobs(jobs, options.sort).map((job) => renderJobRow(job, options));
  return [
    '<table class="jobs">',
    `<thead><tr>${head}</tr></thead>`,
    "<tbody>",
    ...rows,
    "</tbody>",
    `<tfoot><tr><td colspan="${COLUMNS.length}">${pluralize(jobs.length, "job")}</td></tr></tfoot>`,
    "</table>",
  ].join("\n");
}

